function threeSum(nums) {
  nums.sort((a, b) => a - b)
  const result = []
  const n = nums.length
  for (let i = 0; i < n - 2; i++) {
    if (nums[i] > 0) break
    if (i > 0 && nums[i] === nums[i - 1]) continue
    let lo = i + 1
    let hi = n - 1
    while (lo < hi) {
      const total = nums[i] + nums[lo] + nums[hi]
      if (total < 0) lo++
      else if (total > 0) hi--
      else {
        result.push([nums[i], nums[lo], nums[hi]])
        lo++
        hi--
        while (lo < hi && nums[lo] === nums[lo - 1]) lo++
      }
    }
  }
  return result
}

